import {CHANNELS,STATUS} from './core.mjs';
import {workspaceSelect,workspaceCompare} from './app.mjs?v=1.1.0';
import {pageShell,esc,fmt,source,downloadFile} from './ocean-ui.mjs';
import {rowAt,windowRows,windowStats,commonBounds,clampWindow,panWindow,revealFrame,csvCell,initialWindow} from './ocean-data.mjs';
const COLORS=['#36e1f1','#438fff','#c4a1ff','#ffcc80'],KEYS=['GenPwr','PtfmPitch','RotSpeed'];
export function initializeAnalysis(){
 const {page,root}=pageShell('analysis','结果分析','05 / RESPONSE EXPLORER','拖动时间轴，观察同一窗口内的响应。','<button type="button" class="ow-button" id="ow-animation" aria-pressed="false">显示静态</button><button type="button" class="ow-button" id="ow-zoom" aria-pressed="true">全时序视图</button>');
 root.insertAdjacentHTML('beforeend',`<div class="ow-run-strip"><label>当前工况<select id="ow-primary" aria-label="选择分析工况"></select></label><div id="ow-run-meta"></div><button type="button" class="ow-button" id="ow-compare-open">＋ 对比工况</button></div><div class="oa-grid"><section class="oa-plots" aria-label="关联响应曲线">${KEYS.map((key,i)=>`<article class="ow-glass oa-chart ${i===0?'oa-main':''}" data-graph="${key}"><header><h2>${CHANNELS[key].label} <small>${key} / ${CHANNELS[key].unit}</small></h2><div class="oa-legend"></div></header><div class="oa-svg"></div></article>`).join('')}</section><aside class="ow-glass oa-summary"><h2>当前窗口 <small id="oa-window-label"></small></h2><div class="oa-metrics" id="oa-metrics"></div><h3>数据表 <small id="oa-table-note"></small></h3><div class="oa-data-scroll" id="oa-data"></div><p class="ow-muted oa-cursor-label" aria-live="polite"></p></aside></div><section class="ow-glass oa-navigator"><header><h2>时间导航 <small id="oa-domain"></small></h2><span id="oa-play-state">曲线逐步显现</span></header><div class="oa-timeline"><div class="oa-overview"></div><div class="oa-track"><div class="oa-selection" tabindex="0" role="slider" aria-label="平移时间选区" aria-valuemin="0" aria-valuemax="120" aria-valuenow="60"><span></span></div><input type="range" id="oa-range-start" aria-label="时间窗口起点"><input type="range" id="oa-range-end" aria-label="时间窗口终点"></div></div><div class="oa-range-fields"><label>起点 <input type="number" id="oa-start-number" aria-label="窗口起点秒" step="0.1"> s</label><label>终点 <input type="number" id="oa-end-number" aria-label="窗口终点秒" step="0.1"> s</label><button type="button" class="ow-quiet" id="oa-reset-window">恢复原始分析窗口</button><span>拖动选区 · 曲线、统计和数据表同步更新</span></div></section><footer class="ow-page-footer"><p id="oa-provenance"></p><div><button type="button" class="ow-button" data-page="records">运行记录 ↗</button><button type="button" class="ow-primary" id="oa-export">↓ 导出当前窗口</button></div></footer>`);
 const primary=root.querySelector('#ow-primary'),startRange=root.querySelector('#oa-range-start'),endRange=root.querySelector('#oa-range-end'),startNumber=root.querySelector('#oa-start-number'),endNumber=root.querySelector('#oa-end-number'),selection=root.querySelector('.oa-selection'),track=root.querySelector('.oa-track');
 const compare=document.createElement('dialog');compare.className='ow-dialog';compare.innerHTML='<header><h2>选择对比工况</h2><button type="button" aria-label="关闭对比选择">×</button></header><p>最多对比 4 个已完成工况。曲线共用重叠的时间范围。</p><div class="oa-compare-options"></div><button type="button" class="ow-primary oa-compare-apply">应用对比</button>';document.body.append(compare);compare.querySelector('header button').onclick=()=>compare.close();
 let state=null,records=[],bounds=null,start=0,end=120,cursor=0,focusWindow=true,signature='',renderKey='',staticMode=matchMedia('(prefers-reduced-motion:reduce)').matches,animationStart=performance.now(),frame=0,lastFrameTime=0,lastHolding=null,visibilityPaused=false;
 const reduced=matchMedia('(prefers-reduced-motion:reduce)');
 function activate(){const visible=document.body.dataset.page==='analysis'&&!document.hidden;if(visible){if(visibilityPaused)animationStart=performance.now();visibilityPaused=false;if(!frame&&!staticMode)frame=requestAnimationFrame(animate);}else{visibilityPaused=true;cancelAnimationFrame(frame);frame=0;}}
 function animate(now){frame=0;if(document.body.dataset.page!=='analysis'||document.hidden||staticMode)return;if(now-lastFrameTime>25){lastFrameTime=now;const value=revealFrame(now-animationStart);setReveal(value.progress);if(lastHolding!==value.holding){lastHolding=value.holding;root.querySelector('#oa-play-state').textContent=value.holding?'显现完成 · 停留 3 秒':'从左到右显现 · 循环播放';}}frame=requestAnimationFrame(animate);}
 function setReveal(progress){root.querySelectorAll('[data-reveal]').forEach(rect=>rect.setAttribute('width',String(Number(rect.dataset.width)*progress)));}
 function restart(){if(!bounds){cancelAnimationFrame(frame);frame=0;root.querySelector('#oa-play-state').textContent='等待有效结果';return;}animationStart=performance.now();lastHolding=null;setReveal(staticMode?1:0);if(staticMode)root.querySelector('#oa-play-state').textContent='静态显示 · 完整曲线';activate();}
 const animationButton=root.querySelector('#ow-animation');function syncAnimation(){animationButton.textContent=staticMode?'播放动态':'显示静态';animationButton.setAttribute('aria-pressed',String(staticMode));if(staticMode){cancelAnimationFrame(frame);frame=0;}restart();}animationButton.onclick=()=>{staticMode=!staticMode;syncAnimation();};reduced.addEventListener('change',e=>{if(e.matches){staticMode=true;syncAnimation();}});
 root.querySelector('#ow-zoom').onclick=e=>{focusWindow=!focusWindow;e.currentTarget.textContent=focusWindow?'全时序视图':'聚焦选区';e.currentTarget.setAttribute('aria-pressed',String(focusWindow));drawCharts();restart();};
 primary.onchange=()=>workspaceSelect(primary.value);
 root.querySelector('#ow-compare-open').onclick=()=>{compare.querySelector('.oa-compare-options').innerHTML=state.runs.filter(r=>r.status==='completed'&&r.result).map(r=>`<label><input type="checkbox" value="${esc(r.id)}" ${records.some(x=>x.id===r.id)?'checked':''}><span>${esc(r.name)}<small>${source(r)} · ${r.result.analysis_start}—${r.result.analysis_end} s</small></span></label>`).join('');compare.showModal();};
 compare.querySelector('.oa-compare-apply').onclick=()=>{const chosen=[...compare.querySelectorAll('input:checked')].map(input=>input.value);if(chosen.length>4){compare.querySelector('p').textContent='最多选择 4 个工况，请减少选择后再应用。';return;}workspaceCompare(chosen);compare.close();};
 function domain(){return focusWindow?[start,end]:[bounds.min,bounds.max];}
 function linePath(rows,index,x,y){const stride=Math.max(1,Math.ceil(rows.length/1100)),points=rows.filter((_,i)=>i%stride===0);if(points.at(-1)!==rows.at(-1))points.push(rows.at(-1));return points.map((row,i)=>`${i?'L':'M'}${x(row[0]).toFixed(2)},${y(row[index]).toFixed(2)}`).join(' ');}
 function chart(key,index){const width=index===0?900:450,height=index===0?238:195,L=index===0?65:48,R=18,T=26,B=height-32,W=width-L-R,H=B-T,[a,b]=domain();const sets=records.filter(r=>r.result.channels.includes(key)).map(r=>({r,j:r.result.channels.indexOf(key),rows:windowRows(r.result.series,a,b)})).filter(s=>s.rows.length>1);if(!sets.length)return '<div class="ow-empty">该工况尚无此通道的完整时序。</div>';
 let min=Infinity,max=-Infinity;for(const set of sets)for(const row of set.rows){min=Math.min(min,row[set.j]);max=Math.max(max,row[set.j]);}const pad=Math.max((max-min)*.13,Math.abs(max)*.025,.01);min-=pad;max+=pad;if(key==='GenPwr')min=Math.min(min,0);const x=t=>L+(t-a)/(b-a)*W,y=v=>B-(v-min)/(max-min)*H,clip='oa-clip-'+key;
 let svg=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${CHANNELS[key].label}真实响应曲线" data-min="${a}" data-max="${b}" data-ymin="${min}" data-ymax="${max}" data-height="${height}" data-width="${width}" data-left="${L}" data-plot-width="${W}"><defs><clipPath id="${clip}"><rect x="${L}" y="${T}" width="${W}" height="${H}" data-reveal data-width="${W}"/></clipPath></defs><rect x="${x(start)}" y="${T}" width="${x(end)-x(start)}" height="${H}" class="oa-window-shade"/>`;
 for(let i=0;i<=4;i++){const value=min+(max-min)*i/4,yy=y(value);svg+=`<path d="M${L} ${yy}H${width-R}" class="oa-grid-line"/><text x="${L-9}" y="${yy+4}" text-anchor="end">${fmt(value,Math.abs(value)<10?1:0)}</text>`;}
 for(let i=0;i<=6;i++){const t=a+(b-a)*i/6,xx=x(t);svg+=`<path d="M${xx} ${T}V${B}" class="oa-grid-line"/><text x="${xx}" y="${height-10}" text-anchor="middle">${fmt(t,1)}</text>`;}
 svg+=`<g clip-path="url(#${clip})">${sets.map(({r,j,rows})=>`<path d="${linePath(rows,j,x,y)}" fill="none" stroke="${COLORS[records.indexOf(r)%4]}" stroke-width="2.2" vector-effect="non-scaling-stroke"><title>${esc(r.name)}</title></path>`).join('')}</g><line data-cursor-line x1="0" x2="0" y1="${T}" y2="${B}" class="oa-cursor"/><g data-cursor-label><rect x="-31" y="2" width="62" height="21" rx="3"/><text x="0" y="17" text-anchor="middle"></text></g>${sets.map(({r})=>`<circle data-cursor-dot="${esc(r.id)}" r="4" stroke="${COLORS[records.indexOf(r)%4]}"/>`).join('')}<rect x="${L}" y="${T}" width="${W}" height="${H}" fill="transparent" class="oa-hit-area"/></svg>`;return svg;
 }
 function drawCharts(){if(!bounds){root.querySelectorAll('.oa-svg').forEach(node=>node.innerHTML='<div class="ow-empty">等待已完成的仿真结果。可在运行记录中选择真实算例。</div>');return;}KEYS.forEach((key,i)=>{const card=root.querySelector(`[data-graph="${key}"]`);card.querySelector('.oa-svg').innerHTML=chart(key,i);card.querySelector('.oa-legend').innerHTML=records.map((r,j)=>`<span title="${esc(r.name)}"><i style="background:${COLORS[j%4]}"></i>${esc(r.name.split(' · ')[0])}</span>`).join('');});drawCursor();}
 function drawCursor(){if(!bounds)return;const [a,b]=domain();cursor=Math.max(a,Math.min(b,cursor));root.querySelectorAll('[data-graph] svg').forEach(svg=>{const key=svg.closest('[data-graph]').dataset.graph,L=Number(svg.dataset.left),W=Number(svg.dataset.plotWidth),H=Number(svg.dataset.height)-58,xx=L+(cursor-a)/(b-a)*W;svg.querySelector('[data-cursor-line]')?.setAttribute('x1',xx);svg.querySelector('[data-cursor-line]')?.setAttribute('x2',xx);const label=svg.querySelector('[data-cursor-label]');if(label){label.setAttribute('transform',`translate(${Math.max(L+31,Math.min(Number(svg.dataset.width)-49,xx))} 0)`);label.querySelector('text').textContent=fmt(cursor,1)+' s';}svg.querySelectorAll('[data-cursor-dot]').forEach(dot=>{const record=records.find(r=>r.id===dot.dataset.cursorDot),j=record.result.channels.indexOf(key),row=rowAt(record.result.series,cursor);dot.setAttribute('cx',xx);dot.setAttribute('cy',26+H-(row[j]-Number(svg.dataset.ymin))/(Number(svg.dataset.ymax)-Number(svg.dataset.ymin))*H);});});drawTable();}
 function drawTable(){const record=state?.record?.result?state.record:records[0];if(!record?.result||!bounds){root.querySelector('#oa-data').innerHTML='<p class="ow-empty">无可用数据</p>';root.querySelector('#oa-table-note').textContent='';root.querySelector('.oa-cursor-label').textContent='';return;}const {series,channels}=record.result,raw=series.filter(r=>r[0]>=start&&r[0]<=end);let at=raw.findIndex(r=>r[0]>=cursor);if(at<0)at=raw.length-1;const from=Math.max(0,Math.min(raw.length-11,at-5)),rows=raw.slice(from,from+11),keys=['GenPwr','PtfmPitch'];root.querySelector('#oa-table-note').textContent=`选区 ${raw.length} 行`;root.querySelector('#oa-data').innerHTML=`<table><thead><tr><th>时间 s</th><th>功率 kW</th><th>纵摇 °</th></tr></thead><tbody>${rows.map(row=>`<tr data-time="${row[0]}" class="${row===raw[at]?'selected':''}" tabindex="0"><td>${fmt(row[0],1)}</td>${keys.map(key=>`<td>${fmt(row[channels.indexOf(key)],key==='GenPwr'?1:3)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;root.querySelector('.oa-cursor-label').textContent='光标 '+fmt(cursor,1)+' s · 显示附近原始样本';}
 function drawStats(){const record=state?.record?.result?state.record:records[0],stats=record?windowStats(record.result,start,end):null;root.querySelector('#oa-window-label').textContent=bounds?`${fmt(start,1)}—${fmt(end,1)} s`:'暂无数据';const values=[['功率均值',stats?.stats.GenPwr?.mean,'kW'],['纵摇绝对峰值',stats?.stats.PtfmPitch?.max_abs,'°'],['转速均值',stats?.stats.RotSpeed?.mean,'rpm'],['窗口时长',stats?.span,'s']];root.querySelector('#oa-metrics').innerHTML=values.map(([label,value,unit])=>`<div><span>${label}</span><strong>${fmt(value,label.includes('纵摇')?3:1)} <small>${unit}</small></strong></div>`).join('');}
 function drawTimeline(){for(const input of [startRange,endRange,startNumber,endNumber]){input.disabled=!bounds;if(bounds){input.min=bounds.min;input.max=bounds.max;input.step=.1;}}selection.hidden=!bounds;if(!bounds){root.querySelector('.oa-overview').innerHTML='';root.querySelector('#oa-domain').textContent='暂无可用时序';startNumber.value=endNumber.value='';return;}startRange.value=startNumber.value=String(Number(start.toFixed(2)));endRange.value=endNumber.value=String(Number(end.toFixed(2)));const left=(start-bounds.min)/(bounds.max-bounds.min)*100,right=(end-bounds.min)/(bounds.max-bounds.min)*100;selection.style.left=left+'%';selection.style.width=(right-left)+'%';selection.querySelector('span').textContent=`${fmt(start,1)}—${fmt(end,1)} s`;selection.setAttribute('aria-valuemin',bounds.min);selection.setAttribute('aria-valuemax',bounds.max);selection.setAttribute('aria-valuenow',start);selection.setAttribute('aria-valuetext',`${fmt(start,1)} 至 ${fmt(end,1)} 秒`);root.querySelector('#oa-domain').textContent=`${fmt(bounds.min,1)}—${fmt(bounds.max,1)} s`;}
 function setWindow(a,b){if(!bounds)return;[start,end]=clampWindow(bounds,a,b);cursor=Math.max(start,Math.min(end,cursor));drawTimeline();drawStats();drawCharts();restart();}
 startRange.oninput=()=>setWindow(Math.min(Number(startRange.value),end-.1),end);endRange.oninput=()=>setWindow(start,Math.max(Number(endRange.value),start+.1));startNumber.oninput=startNumber.onchange=()=>{if(startNumber.value!=='')setWindow(Math.min(Number(startNumber.value),end-.1),end);};endNumber.oninput=endNumber.onchange=()=>{if(endNumber.value!=='')setWindow(start,Number(endNumber.value));};
 root.querySelector('#oa-reset-window').onclick=()=>{const r=state?.record?.result;if(r&&bounds){setWindow(...initialWindow(bounds,r.analysis_start,r.analysis_end));}};
 let drag=null;selection.onpointerdown=e=>{if(!bounds)return;drag={x:e.clientX,start,end};selection.setPointerCapture(e.pointerId);selection.classList.add('dragging');};selection.onpointermove=e=>{if(!drag)return;const delta=(e.clientX-drag.x)/track.getBoundingClientRect().width*(bounds.max-bounds.min);setWindow(...panWindow(bounds,drag.start,drag.end,delta));};selection.onpointerup=selection.onpointercancel=()=>{drag=null;selection.classList.remove('dragging');};selection.onkeydown=e=>{if(!bounds||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const delta=e.key==='Home'?bounds.min-start:e.key==='End'?bounds.max-end:(e.key==='ArrowRight'?1:-1)*(bounds.max-bounds.min)/100;setWindow(...panWindow(bounds,start,end,delta));};
 root.querySelectorAll('[data-graph]').forEach(card=>card.addEventListener('pointermove',e=>{const svg=card.querySelector('svg');if(!svg||!bounds)return;const box=svg.getBoundingClientRect(),fraction=((e.clientX-box.left)/box.width*Number(svg.dataset.width)-Number(svg.dataset.left))/Number(svg.dataset.plotWidth);if(fraction<0||fraction>1)return;const [a,b]=domain();cursor=a+fraction*(b-a);drawCursor();}));
 root.querySelector('#oa-data').addEventListener('click',e=>{const tr=e.target.closest('[data-time]');if(tr){cursor=Number(tr.dataset.time);drawCursor();}});root.querySelector('#oa-data').addEventListener('keydown',e=>{if(e.key==='Enter')e.target.closest('[data-time]')?.click();});
 root.querySelector('#oa-export').onclick=()=>{if(!bounds||!records.length)return;const columns=['run_id','工况','Time_s','GenPwr_kW','PtfmPitch_deg','RotSpeed_rpm'];const rows=records.flatMap(r=>r.result.series.filter(row=>row[0]>=start&&row[0]<=end).map(row=>[r.id,r.name,row[0],...KEYS.map(key=>row[r.result.channels.indexOf(key)])]));downloadFile(`OpenFAST-窗口-${start.toFixed(1)}-${end.toFixed(1)}s.csv`,'\ufeff'+[columns,...rows].map(row=>row.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');};
 function update(next){state=next;const nextKey=next.runs.map(r=>r.id+':'+r.status).join('|')+'|'+next.record?.id+'|'+next.comparison.join(',');if(nextKey===renderKey)return;renderKey=nextKey;primary.innerHTML=next.runs.map(r=>`<option value="${esc(r.id)}">${esc(r.name)} · ${STATUS[r.status]||r.status}</option>`).join('');primary.value=next.record?.id||'';root.querySelector('#ow-run-meta').innerHTML=next.record?`<span class="ow-dot"></span>${source(next.record)} · ${next.record.params.wind} m/s · ${next.record.params.wave_mode==='regular'?'规则波':'JONSWAP'} ${next.record.params.wave_height} m / ${next.record.params.wave_period} s <b>${STATUS[next.record.status]}</b>`:'选择一个已完成工况';records=next.plots.filter(r=>r.result&&r.status==='completed');if(next.record?.result&&!records.some(r=>r.id===next.record.id))records=[next.record,...records].slice(0,4);bounds=commonBounds(records);const key=next.record?.id+'|'+records.map(r=>r.id).join(',');if(bounds&&key!==signature){signature=key;const r=next.record?.result||records[0].result;[start,end]=initialWindow(bounds,r.analysis_start,r.analysis_end);cursor=(start+end)/2;}drawTimeline();drawStats();drawCharts();if(bounds){const r=records[0].result,j=r.channels.indexOf('GenPwr'),x=t=>(t-bounds.min)/(bounds.max-bounds.min)*1400;let min=Infinity,max=-Infinity;for(const row of r.series){min=Math.min(min,row[j]);max=Math.max(max,row[j]);}const y=v=>45-(v-min)/Math.max(.001,max-min)*34;root.querySelector('.oa-overview').innerHTML=`<svg viewBox="0 0 1400 50" preserveAspectRatio="none" aria-hidden="true"><path d="${linePath(windowRows(r.series,bounds.min,bounds.max),j,x,y)}" fill="none" stroke="#9ac8df" stroke-width="1"/></svg>`;}root.querySelector('#oa-export').disabled=!bounds;root.querySelector('#oa-provenance').textContent=bounds?'真实输出 · 窗口统计不代表年发电量；端点采用线性插值，导出保留原始样本。':'图像与数据将在真实计算完成后显示。';restart();}
 new MutationObserver(activate).observe(document.body,{attributes:true,attributeFilter:['data-page']});document.addEventListener('visibilitychange',activate);syncAnimation();return {update};
}
